class DynamicMLP(tf.keras.Model):
def __init__(self, hidden_dim, num_classes, **kwargs):
super().__init__(**kwargs)
self.dense1 = tf.keras.layers.Dense(hidden_dim, activation="relu")
self.dense2 = tf.keras.layers.Dense(num_classes)

def call(self, inputs, training=False):
x = self.dense1(inputs)
if tf.reduce_mean(x) > 0.5:  # Dynamic control flow
x = x * 2.0
return self.dense2(x)

model = DynamicMLP(hidden_dim=32, num_classes=10)
out = model(tf.random.normal([2, 16]))

